import {avatars,portrait} from './companions.mjs';
import {EXPLORER_COLORS,EXPLORER_SYMBOLS} from './explorer-storage.mjs';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const symbols={leaf:'❧',acorn:'♧',shell:'◉',feather:'❦',pebble:'◆',flower:'✿'};
export function explorerBadge(profile){return profile?`<span class="explorer-marker explorer-color-${esc(profile.color)}" aria-hidden="true">${symbols[profile.symbol]||'✿'}</span><span>${esc(profile.color)} ${esc(profile.symbol)}</span>`:'';}
export function explorerChip(store){return `<button class="explorer-chip" id="explorer-switch" aria-label="Change explorer. Exploring as ${esc(store.active?.color)} ${esc(store.active?.symbol)}"><span>Exploring as</span>${explorerBadge(store.active)}</button>`;}
export function explorerPicker(store,draft,creating=false){const duplicate=store.explorers.some(p=>p.avatar===draft.avatar&&p.color===draft.color&&p.symbol===draft.symbol);return `<div class="page-heading"><a class="back" href="#home" id="explorer-cancel">← Back to the garden</a><h1>${creating?'An explorer of your own':'Who’s exploring?'}</h1><p>Choose a picture, color, and symbol. Each explorer has a separate garden and notebook on this device.</p></div>${!creating?`<section class="explorer-tiles" aria-label="Saved explorers">${store.explorers.map(p=>`<button class="explorer-tile" data-select-explorer="${esc(p.id)}">${portrait(p.avatar)}${explorerBadge(p)}<span>${store.active?.id===p.id?'Here last time':'Visit this garden'}</span></button>`).join('')}<button class="explorer-tile new-explorer" id="explorer-new"><span aria-hidden="true">＋</span>Someone new</button></section>`:`<section class="panel explorer-builder"><h2>Choose an explorer picture</h2><div class="explorer-choice-grid">${avatars.map(a=>`<button class="explorer-tile ${draft.avatar===a.id?'selected':''}" data-explorer-avatar="${a.id}" aria-pressed="${draft.avatar===a.id}">${portrait(a.id)}<span>${esc(a.name)}</span></button>`).join('')}</div><h2>A garden color</h2><div class="explorer-choice-grid colors">${EXPLORER_COLORS.map(c=>`<button class="secondary explorer-color-${c}" data-explorer-color="${c}" aria-pressed="${draft.color===c}">${c}</button>`).join('')}</div><h2>A symbol to find again</h2><div class="explorer-choice-grid symbols">${EXPLORER_SYMBOLS.map(s=>`<button class="secondary" data-explorer-symbol="${s}" aria-pressed="${draft.symbol===s}"><span aria-hidden="true">${symbols[s]}</span> ${s}</button>`).join('')}</div><p class="explorer-preview">${portrait(draft.avatar,true)}${explorerBadge(draft)}</p>${duplicate?'<p role="status">That picture, color, and symbol already belong to an explorer. Choose a different color or symbol.</p>':''}<button class="primary" id="explorer-create" ${duplicate?'disabled':''}>Explore with this picture</button><button class="secondary" id="explorer-back">Choose an existing explorer</button></section>`}<details class="grownup-note"><summary>For grown-ups</summary><p class="tiny">Explorers are local game slots on this device. There is no account, name field, upload, or password. Play saved before explorers were separate is kept in the first explorer.</p></details>`;}
export function explorerNotes(store){
 const copies=store.keptCopies();return `<section class="panel explorer-notes"><h2>This explorer’s notebook</h2><p class="explorer-preview">${portrait(store.active?.avatar,true)}${explorerBadge(store.active)}</p><p>Switching explorers separates every destination, including café jars, reading routes, help, and multiplication practice.</p><div class="summary-links"><button class="secondary" id="notes-switch-explorer">Switch explorer</button><button class="secondary" id="notes-add-explorer">Add another explorer</button><button class="text-button" id="clear-all-explorers">Clear all explorers on this device</button></div>${copies.length?`<details><summary>Earlier and kept saved copies</summary><p>Earlier shared play cannot be separated automatically. Some saved progress may not have been readable; its original text is kept here. Downloads contain local progress: keep them private.</p>${copies.map((c,i)=>`<div class="kept-copy"><span>${esc(c.label)}</span><button class="secondary" data-download-copy="${i}">Download the kept copy</button><button class="text-button" data-remove-copy="${i}">Remove it</button></div>`).join('')}</details>`:''}</section>`;
}
